// ─── Get raw body ─────────────────────────────────────────────────────────────
let rawBody = $input.first().json.body;

let message = '';
let sessionId = '';
let leadData = '';

// ─── Phone Extraction Function ────────────────────────────────────────────────
function extractPhone(input) {
  if (!input) return null;
  const str = typeof input === 'object' ? JSON.stringify(input) : String(input);
  const normalized = str.replace(/[\s\-\(\)\+]/g, '');
  const matches = normalized.match(/[0-9]{9,15}/g);
  if (!matches) return null;
  const filtered = matches.filter(m => {
    return m.length >= 9 && m.length <= 15 && !/^20[0-9]{2}$/.test(m) && !/^[0-9]{4}$/.test(m);
  });
  return filtered.length > 0 ? filtered[0] : null;
}

// ─── Step 1: Try to get fields directly (n8n may auto-parse body) ─────────────
if (typeof rawBody === 'object' && rawBody !== null) {
  message   = rawBody.message   || '';
  sessionId = String(rawBody.sessionId || '');
  leadData  = rawBody.leadData  || '';
}
// ─── Step 2: Body is a string — manual extraction via regex (bypass JSON.parse)
else if (typeof rawBody === 'string') {
  // Extract message
  const msgMatch = rawBody.match(/"message"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  if (msgMatch) message = msgMatch[1];

  // Extract sessionId
  const sidMatch = rawBody.match(/"sessionId"\s*:\s*"([^"]+)"/);
  if (sidMatch) sessionId = sidMatch[1];

  // Extract leadData (everything between "leadData": " and the last closing })" )
  const ldMatch = rawBody.match(/"leadData"\s*:\s*"([\s\S]*?)"\s*\}/);
  if (ldMatch) leadData = ldMatch[1];
}
// ─── Step 3: Fallback — try full json object ──────────────────────────────────
else {
  const fullJson = $input.first().json;
  message   = fullJson.message   || '';
  sessionId = String(fullJson.sessionId || '');
  leadData  = fullJson.leadData  || '';
}

// ─── Extract Phone ────────────────────────────────────────────────────────────
let phone = extractPhone(sessionId);
let phoneSource = 'sessionId';

if (!phone) {
  phoneSource = 'leadData';

  // Try regex on leadData for "phone": "NUMBER" pattern first
  const phoneFieldMatch = String(leadData).match(/"(?:phone|Phone|mobile|number)"\s*:\s*"?([0-9]{9,15})"?/);
  if (phoneFieldMatch) {
    phone = phoneFieldMatch[1];
  } else {
    phone = extractPhone(leadData);
  }
}

if (!phone) {
  phone = 'unknown';
  phoneSource = 'none';
}

// ─── Output ───────────────────────────────────────────────────────────────────
return [{
  json: {
    chatInput:    message,
    phone:        phone,
    sessionId:    phone,
    leadData:     leadData,
    rawSessionId: sessionId,
    phoneSource:  phoneSource
  }
}];

// ULTRA-ROBUST Response Cleaner for EurekaJO
// Handles long responses, property listings, Arabic text, URLs

return items.map(item => {
  try {
    let text = String(item.json.output ?? "");

    // If empty, return default
    if (!text || text.trim() === '') {
      item.json.final_payload = "I'm here to help! What would you like to know?";
      return item;
    }

    // ==========================================
    // PHASE 1: STRUCTURAL CLEANING
    // ==========================================

    // Remove markdown code fences
    text = text.replace(/```(?:json|javascript|js)?\s*/gi, '');
    text = text.replace(/```/g, '');

    // Remove markdown formatting but preserve content
    text = text.replace(/\*\*\*([^*]+)\*\*\*/g, '$1'); // Bold italic
    text = text.replace(/\*\*([^*]+)\*\*/g, '$1');     // Bold
    text = text.replace(/\*([^*]+)\*/g, '$1');         // Italic
    text = text.replace(/__([^_]+)__/g, '$1');         // Bold alt
    text = text.replace(/_([^_]+)_/g, '$1');           // Italic alt

    // Remove headers
    text = text.replace(/^#{1,6}\s+/gm, '');

    // Convert markdown links but preserve URLs
    text = text.replace(/\[([^\]]+)\]\(([^\)]+)\)/g, '$1 - $2');

    // ==========================================
    // PHASE 2: LINE BREAK HANDLING
    // ==========================================

    // Replace Windows line breaks
    text = text.replace(/\r\n/g, ' ');

    // Replace Mac line breaks  
    text = text.replace(/\r/g, ' ');

    // Replace Unix line breaks
    text = text.replace(/\n/g, ' ');

    // Replace vertical tabs and form feeds
    text = text.replace(/[\v\f]/g, ' ');

    // ==========================================
    // PHASE 3: QUOTE HANDLING (CRITICAL!)
    // ==========================================

    // Replace smart/typographic quotes
    text = text.replace(/[\u201C\u201D]/g, '"');  // Curly double quotes
    text = text.replace(/[\u2018\u2019]/g, "'");  // Curly single quotes
    text = text.replace(/[\u201E\u201F]/g, '"');  // Low/high quotes
    text = text.replace(/[\u2032\u2033]/g, '"');  // Prime marks

    // Temporarily protect URLs from quote escaping
    const urlPattern = /(https?:\/\/[^\s]+)/g;
    const urls = [];
    text = text.replace(urlPattern, (match) => {
      urls.push(match);
      return `__URL_PLACEHOLDER_${urls.length - 1}__`;
    });

    // Now handle quotes safely
    // Remove already escaped quotes
    text = text.replace(/\\"/g, '"');
    text = text.replace(/\\'/g, "'");

    // Escape remaining double quotes
    text = text.replace(/"/g, '\\"');

    // Restore URLs
    urls.forEach((url, index) => {
      text = text.replace(`__URL_PLACEHOLDER_${index}__`, url);
    });

    // ==========================================
    // PHASE 4: SPECIAL CHARACTERS
    // ==========================================

    // Remove zero-width characters
    text = text.replace(/[\u200B-\u200D\uFEFF]/g, '');

    // Remove RTL/LTR marks
    text = text.replace(/[\u200E\u200F\u202A-\u202E]/g, '');

    // Remove other invisible characters
    text = text.replace(/[\u00AD\u2060]/g, '');

    // Remove control characters but preserve Arabic
    text = text.replace(/[\u0000-\u0008\u000B-\u001F\u007F-\u009F]/g, '');

    // ==========================================
    // PHASE 5: WHITESPACE NORMALIZATION
    // ==========================================

    // Replace non-breaking spaces with regular spaces
    text = text.replace(/\u00A0/g, ' ');
    text = text.replace(/\u2007/g, ' ');
    text = text.replace(/\u202F/g, ' ');

    // Collapse multiple spaces into one
    text = text.replace(/\s{2,}/g, ' ');

    // Trim leading/trailing whitespace
    text = text.trim();

    // ==========================================
    // PHASE 6: FINAL SAFETY CHECKS
    // ==========================================

    // If text is wrapped in quotes, remove them
    if (text.startsWith('\\"') && text.endsWith('\\"')) {
      text = text.slice(2, -2);
    }

    // Remove any leading/trailing quotes
    text = text.replace(/^["\s]+|["\s]+$/g, '');

    // Replace any remaining problematic escape sequences
    text = text.replace(/\\n/g, ' ');
    text = text.replace(/\\r/g, ' ');
    text = text.replace(/\\t/g, ' ');

    // One final space collapse
    text = text.replace(/\s+/g, ' ').trim();

    // ==========================================
    // PHASE 7: VALIDATION & OUTPUT
    // ==========================================

    // Ensure we have some content
    if (!text || text.length < 2) {
      text = "I'm here to help! What would you like to know?";
    }

    // Store the cleaned text
    item.json.final_payload = text;

    // Test JSON validity
    try {
      const testJson = JSON.stringify({ message: text });
      JSON.parse(testJson);
      item.json.json_valid = true;
    } catch (e) {
      // If still invalid, do nuclear cleaning
      text = text.replace(/[^\w\s\u0600-\u06FF\u0750-\u077F.,!?:;()\-\/']/g, '');
      item.json.final_payload = text;
      item.json.json_valid = false;
      item.json.validation_error = e.message;
    }

    // Add metadata for debugging
    item.json.original_length = String(item.json.output ?? "").length;
    item.json.cleaned_length = text.length;
    item.json.cleaning_timestamp = new Date().toISOString();

    return item;

  } catch (error) {
    // Ultimate fallback - never crash
    item.json.final_payload = "I apologize, there was an issue. Please try again.";
    item.json.error = error.message;
    item.json.error_stack = error.stack;

    return item;
  }
});

return items.map((item) => {
  const b = item.json.body;

  // If body is a string (like "{ \"message\": \"hello\" }"), parse it
  if (typeof b === "string") {
    try {
      item.json.body = JSON.parse(b);
    } catch (e) {
      // If it's not valid JSON, keep it as-is, but you can also store the error
      item.json.body_parse_error = e.message;
    }
  }

  // OPTIONAL: If you want "message" at root level too
  if (item.json.body && item.json.body.message) {
    item.json.message = item.json.body.message;
  }

  return item;
});

return items.map(item => {
  const text = String(item.json.output ?? "");

  const clean = text
    .replace(/\r?\n+/g, " ")     // remove ALL line breaks
    .replace(/[\u0000-\u001F]/g, "") // remove hidden control chars
    .replace(/\s+/g, " ")
    .trim();

  item.json.final_payload = clean;
  return item;
});

return items.map((item) => {
  const b = item.json.body;

  let bodyData = b;
  // Safety check: Agar body string format mein aaye
  if (typeof b === "string") {
    try {
      bodyData = JSON.parse(b);
    } catch (e) {}
  }

  return {
    json: {
      // Message uthao
      chatInput: bodyData.message || "",

      // Yahan magic hai: Agar ID aayi to wo use karo, nahi to "test_user" use karo
      sessionId: bodyData.sessionId || "test_user_123" 
    }
  };
});

return items.map((item) => {
  let raw = item.json.body;
  let bodyData = {};

  if (typeof raw === "string") {
    try {
      bodyData = JSON.parse(raw);
    } catch (e) {
      bodyData = { message: raw, sessionId: "" };
    }
  } else if (typeof raw === "object" && raw !== null) {
    bodyData = raw;
  }

  // SessionId extract karo
  let sessionId = "";
  if (bodyData.sessionId !== undefined && bodyData.sessionId !== null) {
    sessionId = String(bodyData.sessionId).trim();
  }

  // Agar sessionId empty hai to IP se banao
  if (!sessionId || sessionId.length === 0) {
    const headers = item.json.headers || {};

    // Real IP nikalo (Cloudflare ke through aata hai)
    const ip = headers["cf-connecting-ip"] 
             || headers["x-real-ip"] 
             || headers["x-forwarded-for"]?.split(",")[0]?.trim()
             || "unknown";

    const userAgent = headers["user-agent"] || "unknown";

    // IP + UserAgent ko mila ke stable ID banao
    sessionId = `guest_${ip}_${userAgent.slice(0, 20).replace(/\s+/g, "_")}`;
  }

  let chatInput = "";
  if (bodyData.message !== undefined && bodyData.message !== null) {
    chatInput = String(bodyData.message).trim();
  }

  return {
    json: {
      chatInput,
      sessionId,
    }
  };
});
